     */
    resetTimeoutMs?: number;
    /**
     * Request timeout for health checks (ms, default: 3_000).
     */
    probeTimeoutMs?: number;
}

AuditLogger:
/**
 * Structured JSON audit logger (SOC2 CC7.1).
 *
 * Produces one JSON object per line on stdout. Pipe to cloud logging
