 *
 * @example
 * ```typescript
 * const logger = new AuditLogger({ service: 'my-app' });
 * logger.log({ type: 'auth.login.success', userId: 'u123' });
 * // → {"level":"info","service":"my-app","type":"auth.login.success","userId":"u123","timestamp":"..."}
